#!/usr/bin/env bash
REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
SAT="${REPO_ROOT}/SAT.evolution.scripts"

#sat113_manifest.tsv contains paths to some of the files generated by the SAT_array_pipeline_v2.sh pipeline.
export MAX_SUBTYPES=18
export MODEL_STARTS=24
export CV_FOLDS=5
export CV_STARTS=4
export EXCLUDE_CORE_EDGE_SITES=5
export RUN_TREE=1
bash "${SAT}/run_sat_variant_origin.sh" "${SAT}/sat113_manifest.tsv" PPA.FCA.PTI.SAT113.phase.origin.fixed.k18.other 20

export MAX_SUBTYPES=18
export MODEL_STARTS=8
export CV_FOLDS=5
export CV_STARTS=2
export EXCLUDE_CORE_EDGE_SITES=0
export RUN_TREE=1
bash "${SAT}/run_sat_variant_origin.sh" "${SAT}/sat113_manifest.tsv" PPA.FCA.PTI.SAT113.phase.origin.fixed.k18 20

export MAX_SUBTYPES=12
export MODEL_STARTS=8
export CV_FOLDS=5
export CV_STARTS=2
export EXCLUDE_CORE_EDGE_SITES=5
export RUN_TREE=1
bash "${SAT}/run_sat_variant_origin.sh" "${SAT}/sat483_manifest.tsv" PPA.FCA.PTI.SAT483.origin 20

#combine primary and sensitive SAT113 results
Rscript "${SAT}/plot_SAT113_variant_results.R" \
  --primary-dir PPA.FCA.PTI.SAT113.phase.origin.fixed.k18 \
  --sensitivity-dir PPA.FCA.PTI.SAT113.phase.origin.fixed.k18.other \
  --outdir SAT113_R_figures \
  --main-threshold 0.85 \
  --formats pdf,png \
  --layout all

#replot for SAT483
Rscript "${SAT}/plot_variant_results_2dp.R" PPA.FCA.PTI.SAT483.origin/results

#Detect arrays that may contain HOR structures. 
Rscript "${SAT}/plot_satellite_HOR_evidence.v2.0.0.R" --input PPA.FCA.PTI.SAT113.phase.origin.fixed.k18/results --mode auto --outdir SAT113_HOR_analysis --dpi 600
